node -e "
const sqlite = require('node:sqlite');
const db = new sqlite.DatabaseSync('/workspace/world.db');

// Find user by email
const user = db.prepare(\"SELECT * FROM users WHERE email = 'caleb.foster@email.com' AND skill_ids_json LIKE '%tau2Retail%'\").get();
if (!user) { console.log('User not found'); process.exit(1); }
console.log('=== USER ===');
console.log(JSON.stringify(user, null, 2));

// Get payment methods
const pms = db.prepare('SELECT * FROM rt_payment_methods WHERE user_id = ?').all(user.user_id);
console.log('=== PAYMENT METHODS ===');
console.log(JSON.stringify(pms, null, 2));

// Get orders
const orders = db.prepare(\"SELECT order_id, status FROM orders WHERE customer_id = ? AND source_skill = 'tau2Retail'\").all(user.user_id);
console.log('=== ORDERS ===');
console.log(JSON.stringify(orders, null, 2));

db.close();
"

node -e "
const sqlite = require('node:sqlite');
const db = new sqlite.DatabaseSync('/workspace/world.db');

// Search broadly for this email
const user = db.prepare(\"SELECT * FROM users WHERE email = 'caleb.foster@email.com'\").get();
console.log('Broad search:', JSON.stringify(user, null, 2));

// Also check how many users exist
const count = db.prepare('SELECT COUNT(*) as cnt FROM users').get();
console.log('Total users:', count.cnt);

// Check for similar emails
const similar = db.prepare(\"SELECT user_id, email, skill_ids_json FROM users WHERE email LIKE '%caleb%' OR email LIKE '%foster%'\").all();
console.log('Similar emails:', JSON.stringify(similar, null, 2));

db.close();
"

